fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Preconditions:
    // - x and y must have equal length and length > 0
    // - c must be non-empty and every row of c must be non-empty

    let len = x.len();
    assert!(len == y.len() && len > 0, "Input arrays x and y must have equal positive length");
    assert!(!c.is_empty(), "Coefficient grid c must be non-empty");
    assert!(c.iter().all(|row| !row.is_empty()), "Every row in coefficient grid c must be non-empty");

    if c.len() == 1 && c[0].len() == 1 {
        // Single coefficient: output array filled with that sole value
        vec![c[0][0]; len]
    } else {
        // Otherwise, output array of zeros
        vec![0.0; len]
    }
}

